description:
, and the rendered body in .
    Readers keyed to either element keep working only if both are present, so the
    shape is reproduced here rather than replaced with Zola's default.
    The window is applied with a loop guard because this Tera build has no
    `slice` filter. -#}

    
      {{ config.title }}
      {{ config.base_url | escape_xml | safe }}/
      
      {{ config.description }}
      {%- if last_updated is defined %}
      {{ last_updated | date(format="%a, %d %b %Y %H:%M:%S GMT", timezone="UTC") }}
      {%- endif %}
      {{ lang }}
      Zola
      {%- for page in pages %}{% if loop.index0 < 10 %}


          {{ page.title }}
          {{ page.permalink | escape_xml | safe }}
          {#- The Lume feed marked the guid as a non-permalink. Dropping the
              attribute changes how a reader derives an item's identity, which
              can make every existing item look new exactly once. -#}
          {{ page.permalink | escape_xml | safe }}
          {{ page.date | date(format="%a, %d %b %Y %H:%M:%S GMT", timezone="UTC") }}
          {{ page.description | default(value="") }}
          {{ page.content | safe }}
      
      {%- endif %}{%- endfor %}
